    const factorNote = vf !== 1 || pf !== 1 ? `（已乘情景系数：${vName}×${vf}，${pName}×${pf}）` : '';
    const series = (get) => Object.fromEntries(years.map((yy) => [yy, pOf(yy) ? get(pOf(yy), fOf(yy)) : null]));

    // ---------- 利润：营收 → 利润总额 → 归母净利 → 股息 ----------
