              <Col span={12}><Card size="small"><Statistic title="ROE（归母净利÷平均归母权益）" value={pct(b.roe)} /></Card></Col>
              <Col span={12}><Card size="small"><Statistic title="带息负债率（÷带息负债＋全部权益）" value={pct(b.debt_to_capital)} /></Card></Col>
