    const rollColumns = [
      { title: '科目 · 是什么', key: 'item', width: 230, render: (_, r) => (
        <div><div style={{ fontWeight: r.strong ? 600 : 400 }}>{r.item}</div>{r.what && <Text type="secondary" style={{ fontSize: 12 }}>{r.what}</Text>}</div>) },
