    const bsTab = !bsOk ? (
      <Alert type="info" showIcon message="还没有期初资产负债"
        description="到「估值模型」填写基准年末的经营性长期资产、长期股权投资、带息负债、归母权益、少数股东权益（亿元），这里就会逐年滚动。" />
