                  { n: '带息负债', v: cur.debt, c: PALETTE.debt }, { n: '少数股东权益', v: cur.mi, c: PALETTE.mi }, { n: '归母权益', v: cur.eq, c: PALETTE.eq }]} />
              </div>
              {cur.other < 0 && (
                <Text type="secondary" style={{ fontSize: 12 }}>
